#include "fft_t1fv6_gpu.h"
#include <vulkan_instance.h>
#include <bit>
#include <fstream>
#include <filesystem>
#include <iostream>
std::vector<float> load(const std::filesystem::path&p){auto size=std::filesystem::file_size(p);if(size%4)throw std::runtime_error("Layout");std::vector<float> v(size/4);std::ifstream f(p,std::ios::binary);f.read((char*)v.data(),size);if(!f)throw std::runtime_error("Read");return v;}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("Usage shader native-fixture-root fresh-out");std::filesystem::path out=argv[3],root=argv[2];if(std::filesystem::exists(out))throw std::runtime_error("Fresh output required");std::filesystem::create_directories(out);auto input=load(root/"t1fv6_input.f32"),expected=load(root/"t1fv6_expected.f32");if(input.size()!=4802*48||expected.size()!=input.size())throw std::runtime_error("Fixture count");IQM::Bin::VulkanInstance gpu(true,"",true);std::ofstream rows(out/"results.jsonl");size_t mismatch=0,values=0,offset=0;for(unsigned batches:{1u,63u,64u,65u,513u,4096u}){auto actual=IQM::HDRVDP3::fft_t1fv6_gpu(gpu,argv[1],std::span<const float>(input.data()+offset,batches*48));if(actual.size()!=batches*48)throw std::runtime_error("Output shape");size_t bits=0;for(size_t i=0;i<actual.size();i++)if(std::bit_cast<uint32_t>(actual[i])!=std::bit_cast<uint32_t>(expected[offset+i])){if(bits<4)std::cout<<"i="<<i<<" exp="<<std::hex<<std::bit_cast<uint32_t>(expected[offset+i])<<" actual="<<std::bit_cast<uint32_t>(actual[i])<<std::dec<<std::endl;bits++;}rows<<"{\"batches\":"<<batches<<",\"values\":"<<actual.size()<<",\"bit_mismatches\":"<<bits<<"}\n";std::cout<<batches<<" batches bits="<<bits<<std::endl;mismatch+=bits;values+=actual.size();offset+=actual.size();}std::ofstream(out/"summary.json")<<"{\"exact\":"<<(mismatch?"false":"true")<<",\"values\":"<<values<<",\"bit_mismatches\":"<<mismatch<<",\"scope\":\"isolated native4K t1fv6 forward stage; not full FFT24 or4K transform\"}";return mismatch?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
